INSERT INTO products (id, slug, name, category_id, brand_id, packaging_label, description, origin, rating_avg, review_count, sold_count_label, unit_label, is_perishable, stock_status, is_featured, is_new, on_sale, is_hidden) VALUES
  (1, 'bot-mi-baker-s-choice-so-8-1', 'Bột mì Baker\'s Choice số 8', 1, 1, 'Gói 1kg', 'Bột mì số 8 có hàm lượng protein thấp (8-9%), thích hợp làm bánh bông lan, cupcake, muffin và các loại bánh mềm xốp.', 'Việt Nam', '4.80', 124, '1.8k', 'gói', 0, 'in_stock', 1, 0, 1, 0),
  (2, 'bot-mi-baker-s-choice-so-11-2', 'Bột mì Baker\'s Choice số 11', 1, 1, 'Gói 1kg', 'Bột mì số 11 giàu protein phù hợp làm bánh mì hoa cúc, baguette và các loại bánh cần kết cấu dai, đàn hồi.', 'Việt Nam', '4.70', 86, '1.2k', 'gói', 0, 'in_stock', 1, 0, 1, 0),
  (3, 'bot-mi-da-dung-meizan-3', 'Bột mì đa dụng Meizan', 1, 2, 'Gói 1kg', 'Bột mì đa dụng tiện lợi có thể sử dụng linh hoạt cho bánh quy bơ, muffin, pancake và chế biến thực phẩm.', 'Việt Nam', '4.90', 185, '1.5k', 'gói', 0, 'in_stock', 1, 0, 1, 0),
  (4, 'bot-cacao-nguyen-chat-hershey-s-4', 'Bột cacao nguyên chất Hershey\'s', 1, 3, 'Hộp 100g', 'Bột cacao nguyên chất không đường dùng tạo hương vị chocolate đậm đà cho brownie, bánh quy và mousse.', 'Mỹ', '4.90', 98, '1.1k', 'hộp', 0, 'in_stock', 1, 1, 1, 0),
  (5, 'bot-matcha-lam-banh-5', 'Bột Matcha', 1, 9, 'Gói 100g', 'Bột matcha trà xanh nghiền mịn dùng làm cupcake, chiffon, tiramisu và các món tráng miệng chuẩn vị Nhật.', 'Nhật Bản', '4.80', 74, '680', 'gói', 0, 'in_stock', 1, 1, 1, 0),
  (6, 'whipping-cream-anchor-6', 'Whipping Cream Anchor', 1, 5, 'Hộp 250ml', 'Kem tươi béo mịn 35.1% dùng để đánh bông, chà láng trang trí bánh kem, làm mousse và panna cotta.', 'New Zealand', '4.80', 156, '1.9k', 'hộp', 1, 'in_stock', 0, 0, 1, 0),
  (7, 'can-dien-tu-nha-bep-7', 'Cân điện tử nhà bếp', 2, 6, 'Mẫu 5kg / 1g', 'Cân điện tử độ chia 1g hỗ trợ cân đo chính xác bột, đường, bơ và định lượng chuẩn theo từng công thức bánh.', 'Nhập khẩu', '4.80', 112, '920', 'cái', 0, 'in_stock', 1, 0, 0, 0),
  (8, 'ca-dong-nguyen-lieu-8', 'Ca đong nguyên liệu', 2, 6, 'Ca 500ml', 'Ca đong nhựa nguyên sinh có vạch chia ml và cup rõ nét giúp đo lường nước, sữa và nguyên liệu lỏng.', 'Việt Nam', '4.70', 64, '780', 'cái', 0, 'in_stock', 0, 0, 0, 0),
  (9, 'thia-dong-dinh-luong-9', 'Thìa đong định lượng', 2, 6, 'Bộ 5 thìa', 'Bộ 5 thìa đong tsp/tbsp hỗ trợ định lượng chuẩn các nguyên liệu nhỏ như bột nở, baking soda, muối và vani.', 'Nhập khẩu', '4.80', 79, '1.0k', 'bộ', 0, 'in_stock', 0, 1, 0, 0),
  (10, 'nhiet-ke-dien-tu-nha-bep-10', 'Nhiệt kế điện tử nhà bếp', 2, 6, 'Đầu dò tiêu chuẩn', 'Nhiệt kế đầu dò inox hỗ trợ kiểm tra nhiệt độ đường thắng caramel, nước kích men nở và socola đun chảy.', 'Nhập khẩu', '4.70', 49, '540', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (11, 'tui-bat-kem-dung-mot-lan-11', 'Túi bắt kem dùng một lần', 3, 6, 'Túi 50 cái', 'Túi bắt kem nhựa PE dày vân nhám chống trượt hỗ trợ tạo hình su kem, trang trí bánh kem và cupcake.', 'Việt Nam', '4.90', 88, '1.4k', 'gói', 0, 'in_stock', 0, 0, 0, 0),
  (12, 'bo-lat-anchor-227g-12', 'Bơ lạt Anchor', 1, 5, 'Khối chuẩn', 'Bơ lạt nhập khẩu New Zealand làm từ sữa bò tươi tự nhiên, mang lại hương thơm béo ngậy cho bánh quy và bánh mì hoa cúc.', 'New Zealand', '3.50', 214, '2.3k', 'khối', 1, 'in_stock', 1, 0, 1, 0),
  (13, 'duong-tinh-luyen-bien-hoa-1kg-13', 'Đường tinh luyện Biên Hòa', 1, 7, 'Túi 1kg', 'Đường cát trắng tinh luyện hạt mịn dễ tan khi đánh cùng trứng và bơ, phù hợp cho mọi loại bánh ngọt.', 'Việt Nam', '4.80', 142, '2.1k', 'túi', 0, 'in_stock', 0, 0, 0, 0),
  (14, 'cream-of-tartar-baker-s-100g-14', 'Bột làm bánh Tartar', 1, 1, 'Hộp 100g', 'Bột ổn định lòng trắng trứng giúp bọt khí bền vững khi đánh bông làm bánh bông lan chiffon và meringue.', 'Nhập khẩu', '4.90', 68, '890', 'hộp', 0, 'in_stock', 0, 0, 1, 0),
  (15, 'trung-ga-tuoi-chuan-vi-vi-10-qua-15', 'Trứng gà', 1, 8, 'Vỉ 10 quả', 'Vỉ 10 trứng gà tươi chọn lọc kích cỡ đồng đều (55-60g/quả), lòng đỏ sánh đậm giúp bánh lên màu vàng ươm.', 'Việt Nam', '4.90', 173, '2.4k', 'vỉ', 1, 'in_stock', 0, 0, 0, 0),
  (16, 'phoi-long-danh-trung-inox-16', 'Phới lồng đánh trứng Inox', 2, 6, 'Cỡ 25cm', 'Phới lồng thép không gỉ tay cầm gỗ chắc chắn giúp đánh bông lòng đỏ, trộn đều hỗn hợp bột và sốt kem mịn mượt.', 'Nhập khẩu', '4.80', 62, '740', 'cái', 0, 'in_stock', 0, 0, 1, 0),
  (17, 'khuon-banh-bong-lan-tron-chong-dinh-20cm-17', 'Khuôn bánh bông lan tròn chống dính', 2, 6, 'Đường kính 20cm', 'Khuôn đế rời đường kính 20cm truyền nhiệt đều và phủ chống dính an toàn, giúp tách bánh bông lan dễ dàng.', 'Nhập khẩu', '4.90', 105, '980', 'cái', 0, 'in_stock', 1, 1, 1, 0),
  (18, 'giay-nen-nuong-banh-chong-dinh-cuon-5m-18', 'Giấy nến nướng bánh chống dính', 3, 6, 'Cuộn 5m × 30cm', 'Giấy nến phủ silicone chống dính 2 mặt chịu nhiệt tới 230°C, giúp lót khay nướng cookie và khuôn bánh sạch sẽ.', 'Việt Nam', '4.80', 132, '1.7k', 'cuộn', 0, 'in_stock', 0, 0, 0, 0),
  (19, 'cup-giay-nuong-banh-cupcake-50-cai-19', 'Cup giấy nướng bánh Cupcake', 3, 6, 'Lốc 50 cup', 'Bộ 50 cup giấy xếp ly dày dặn chống thấm dầu, giữ phom bánh cupcake và muffin đứng đẹp trong lò nướng.', 'Việt Nam', '4.90', 118, '1.6k', 'lốc', 0, 'in_stock', 0, 1, 0, 0),
  (20, 'bo-dui-bat-kem-inox-12-dau-20', 'Bộ đui bắt kem Inox', 3, 6, 'Bộ 12 đui + khớp nối', 'Bộ 12 đui tạo hình sao, hoa hồng, lá, viền sò bằng inox 304 liền khối kèm khớp nối tiện lợi cho trang trí bánh.', 'Nhập khẩu', '4.90', 94, '1.1k', 'bộ', 0, 'in_stock', 0, 1, 1, 0),
  (21, 'hop-giay-dung-banh-kem-co-quai-xach-21', 'Hộp giấy đựng bánh kem có quai xách', 3, 6, 'Set 2 hộp (25×25×18cm)', 'Hộp đựng bánh kích thước 25x25x18cm có quai xách chắc chắn và cửa sổ mica trong suốt sang trọng để mang biếu tặng.', 'Việt Nam', '4.80', 77, '960', 'set', 0, 'in_stock', 0, 0, 0, 0),
  (24, 'sua-tuoi-vinamilk-24', 'Sữa Tươi Tiệt Trùng Không Đường Vinamilk 100%', 1, 10, 'Hộp 1 Lít', 'Sữa tươi 100% nguyên chất không đường, vị thanh nhẹ tự nhiên giúp dễ dàng cân chỉnh độ ngọt chuẩn xác khi làm bánh, pha chế và nấu sốt kem.', 'Việt Nam', '4.90', 312, '4.5k', 'hộp', 1, 'in_stock', 1, 1, 1, 0),
  (25, 'la-gelatine-ewald-bronze-25', 'Lá Gelatine Ewald Bronze', 1, 11, 'Gói chiết lẻ 100g', 'Lá Gelatine Ewald dòng Bronze nhập khẩu chính hãng từ Đức, độ tinh khiết cao giúp tạo độ đông đàn hồi chuẩn xác cho mousse, panna cotta, thạch và kẹo dẻo.', 'Đức', '4.90', 168, '2.3k', 'hộp', 0, 'in_stock', 0, 1, 1, 0),
  (26, 'baking-soda-arm-hammer-26', 'Baking Soda', 1, 12, 'Hộp 226g', 'Bột nở Baking Soda nguyên chất số 1 tại Mỹ, giúp tạo độ xốp, trung hòa axit và hỗ trợ nở bánh quy, bánh muffin, bánh bông lan hiệu quả.', 'Mỹ', '4.90', 245, '3.1k', 'hộp', 0, 'in_stock', 0, 1, 1, 0),
  (27, 'men-no-mauripan-27', 'Men nở', 1, 13, 'Gói lẻ 10g', 'Men nở khô instant Mauripan chuyên dụng cho các loại bánh mì ngọt, bánh mì sandwich, giúp bột nở nhanh, đều và không bị đắng hậu vị.', 'Anh', '4.90', 195, '3.8k', 'gói', 0, 'in_stock', 1, 1, 1, 0),
  (28, 'may-danh-trung-philips-hr3705-28', 'Máy Đánh Trứng Cầm Tay Philips HR3705', 2, 14, 'Nguyên bộ', 'Máy đánh trứng cầm tay Philips HR3705 công suất 300W mạnh mẽ, thiết kế hiện đại với 5 cấp độ tốc độ và chức năng turbo, giúp đánh bông kem, lòng trắng trứng và nhào bột nhẹ nhàng.', 'Hà Lan', '4.90', 142, '890', 'bộ', 0, 'in_stock', 1, 1, 1, 0),
  (29, 'to-tron-inox-sanneng-29', 'Tô Trộn Inox', 2, 15, 'Tô đơn lẻ size 22cm', 'Tô trộn inox 304 cao cấp chuyên dụng làm bánh, lòng sâu chống bắn, sáng bóng, an toàn vệ sinh thực phẩm và chịu nhiệt tốt. Có thể mua lẻ từng kích thước hoặc mua trọn bộ tiện lợi.', 'Trung Quốc', '4.90', 178, '1.4k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (30, 'ray-bot-sanneng-30', 'Rây Bột', 2, 15, 'Size 16cm', 'Rây lọc bột inox 304 mắt lưới siêu mịn, thiết kế tay cầm dài chắc chắn kèm tai móc gác lên miệng tô tiện lợi, giúp rây bột tơi xốp và lọc hỗn hợp kem trứng mịn mượt không lợn cợn.', 'Đài Loan', '4.90', 162, '2.1k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (31, 'khuon-nuong-cupcake-muffin-31', 'Khuôn Nướng Cupcake & Muffin', 2, 15, 'Khay 6 lỗ chuẩn', 'Khuôn nướng 6 lỗ chuyên dụng làm cupcake và muffin, chất liệu thép carbon chịu nhiệt cao phủ lớp chống dính cao cấp giúp lấy bánh dễ dàng và dễ vệ sinh.', 'Trung Quốc', '4.90', 158, '1.6k', 'cái', 0, 'in_stock', 1, 1, 1, 0),
  (32, 'khuon-silicon-silikomart-32', 'Khuôn Silicon', 2, 16, '5 ô', 'Khuôn silicon thực phẩm cao cấp dẻo dai, chịu nhiệt cực tốt từ -40°C đến 230°C, chuyên dùng làm socola, kẹo dẻo, thạch hoặc bánh nướng nhỏ.', 'Ý', '4.80', 134, '1.1k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (33, 'ban-xoay-banh-kem-sanneng-33', 'Bàn Xoay Bánh Kem', 2, 15, 'Đường kính 27.5cm', 'Bàn xoay làm bánh chuyên dụng bằng nhựa ABS cao cấp, trục bi xoay êm ái 360 độ giúp chà láng mặt bánh kem và trang trí bánh dễ dàng, chuẩn xác.', 'Đài Loan', '4.90', 185, '1.5k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (34, 'hop-dung-cupcake-sanneng-34', 'Hộp Đựng Cupcake', 3, 15, 'Hộp 1 bánh', 'Hộp giấy đựng cupcake chuyên dụng thiết kế sang trọng, có vỉ định hình giúp cố định bánh chắc chắn không bị dịch chuyển khi vận chuyển.', 'Đài Loan', '4.90', 142, '1.2k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (35, 'tui-giay-kraft-dung-banh-35', 'Túi Giấy Kraft Đựng Bánh', 3, 15, 'Size S', 'Túi giấy kraft đựng bánh thiết kế đáy vuông dày dặn, quai xách chắc chắn, sang trọng và lịch sự, phù hợp đựng các hộp bánh đem biếu tặng hoặc giao cho khách.', 'Đài Loan', '4.90', 210, '2.5k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (36, 'tui-zip-dung-banh-36', 'Túi Zip Đựng Bánh', 3, 15, 'Size trung bình đa năng', 'Túi zip đựng bánh thiết kế khóa miết kín khít, chất liệu nhựa trong suốt dẻo dai giúp bảo quản bánh cookies, kẹo và các loại hạt khô tránh bị ỉu, ẩm mốc.', 'Đài Loan', '4.90', 165, '2.8k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (37, 'de-banh-kem-sanneng-37', 'Đế Bánh Kem', 3, 15, 'Đế tròn 20cm', 'Đế lót bánh kem chuyên dụng cứng cáp, chịu lực tốt, giúp cố định form bánh sinh nhật và bánh gato dễ dàng di chuyển mà không bị biến dạng.', 'Đài Loan', '4.90', 175, '3.4k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (38, 'khay-giay-dung-banh-nap-trong-38', 'Khay Giấy Đựng Bánh Kèm Nắp Trong', 3, 15, 'Size S', 'Khay giấy kraft đựng bánh thiết kế đáy vuông kết hợp nắp nhựa trong suốt cao cấp, giúp bảo quản và khoe trọn vẻ đẹp của các loại bánh su kem, bánh cuộn, tiramisu hoặc bánh mì ngọt.', 'Đài Loan', '4.90', 156, '2.3k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (39, 'khay-nhom-nuong-banh-sanneng-39', 'Khay Nhôm Nướng Bánh', 2, 15, 'Khay thành thấp', 'Khay nhôm nướng bánh cao cấp chuyên dụng cho lò nướng, thiết kế phẳng đều giúp truyền nhiệt cực tốt, giúp bánh chín vàng đều các mặt. Có phân loại thành cao và thành thấp tùy nhu cầu sử dụng.', 'Đài Loan', '4.90', 192, '2.6k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (40, 'de-lot-banh-mousse-40', 'Đế Lót Bánh Mousse', 3, 15, 'Đế mousse mini tròn 5cm', 'Tấm đế lót chuyên dụng cho bánh mousse, tiramisu và bánh ngọt nhỏ, thiết kế gọn gàng giúp cố định bánh đẹp mắt và thuận tiện khi cầm nắm, thưởng thức.', 'Đài Loan', '4.90', 188, '3.1k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (41, 'nen-sinh-nhat-sanneng-41', 'Nến Sinh Nhật', 3, 15, 'Nến số 0-9', 'Nến sinh nhật sáp thực vật an toàn ít khói với nhiều mẫu thời thượng: nến số, nến xoắn pastel, nến dài thanh mảnh và nến kim tuyến.', 'Đài Loan', '4.80', 83, '2.1k', 'bộ', 0, 'in_stock', 0, 1, 1, 0),
  (42, 'topper-trang-tri-banh-sinh-nhat-42', 'Topper Trang Trí Bánh Sinh Nhật', 3, 15, 'Topper Happy Birthday', 'Phụ kiện que cắm topper trang trí bánh sinh nhật chất liệu acrylic sáng bóng và giấy ép kim sắc nét, tạo điểm nhấn nổi bật cho chiếc bánh.', 'Đài Loan', '4.90', 91, '1.7k', 'cái', 0, 'in_stock', 0, 1, 1, 0),
  (43, 'sticker-niem-phong-sanneng-43', 'Sticker Niêm Phong', 3, 15, 'Cuộn tiêu chuẩn', 'Tem dán niêm phong hộp bánh và túi bánh handmade sắc nét keo bám chắc, tạo sự chỉn chu chuyên nghiệp cho quà tặng.', 'Đài Loan', '4.90', 119, '3.1k', 'cuộn', 0, 'in_stock', 0, 1, 1, 0),
  (44, 'ruy-bang-sanneng-44', 'Ruy Băng', 3, 15, 'Cuộn 1m', 'Dây ruy băng lụa satin cao cấp bản đẹp giúp thắt nơ hộp bánh kem, hộp cookie biếu tặng cực kỳ tinh tế.', 'Đài Loan', '4.80', 77, '2.0k', 'cuộn', 0, 'in_stock', 0, 1, 1, 0),
  (45, 'hu-nhua-dung-thuc-pham-45', 'Hũ Nhựa Đựng Thực Phẩm', 3, 15, 'Size S', 'Hũ nhựa PET trong suốt nắp vặn kín khí đạt chuẩn an toàn thực phẩm, lý tưởng đựng bánh quy, tiramisu, bông lan trứng muối và hạt khô.', 'Đài Loan', '4.80', 68, '1.6k', 'hũ', 0, 'in_stock', 0, 1, 1, 0),
  (46, 'lo-thuy-tinh-dung-thuc-pham-46', 'Lọ Thủy Tinh Đựng Thực Phẩm', 3, 15, 'Size S', 'Lọ thủy tinh dày chịu nhiệt nắp thiếc/gỗ kín hơi chuyên đựng sữa chua, panna cotta, pudding nướng và bảo quản nguyên liệu bột khô.', 'Đài Loan', '4.90', 72, '1.2k', 'lọ', 0, 'in_stock', 0, 1, 1, 0),
  (47, 'kep-mieng-tui-thuc-pham-47', 'Kẹp Miệng Túi Thực Phẩm', 3, 15, 'Cái tiêu chuẩn 11cm', 'Thanh kẹp miệng túi nhựa PP chắc chắn giúp khóa kín các túi bột mì, đường, hạt và túi bánh ăn dở không bị ẩm.', 'Đài Loan', '4.80', 61, '1.8k', 'cái', 0, 'in_stock', 0, 1, 1, 0);
