  (1, 'Công dụng phù hợp', 'Thích hợp làm bánh bông lan, chiffon, cupcake, muffin và các loại bánh mềm xốp.', 4),
  (1, 'Hướng dẫn sử dụng', 'Rây mịn bột trước khi trộn để hỗn hợp tơi xốp và không vón cục.', 5),
