  (4, 'Đặc điểm hương vị', 'Màu nâu đậm tự nhiên, vị chocolate nguyên bản, hương thơm nồng ấm', 3),
  (4, 'Ứng dụng phù hợp', 'Tạo hương vị chocolate đậm đà cho brownie, muffin, bánh quy và mousse.', 4),
