  (24, 'Ứng dụng phù hợp', 'Làm cốt bánh bông lan, bánh flan, panna cotta, nhân kem trứng (custard) và nhào bột bánh mì', 4),
  (24, 'Hướng dẫn sử dụng', 'Lắc đều trước khi dùng. Dùng trực tiếp ở nhiệt độ phòng hoặc đun ấm nhẹ tùy theo yêu cầu công thức', 5),
  (24, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát khi chưa mở nắp. Sau khi mở nắp, đậy kín và bảo quản ngăn mát tủ lạnh (2–4°C), dùng hết trong 3–4 ngày', 6),
  (25, 'Mã sản phẩm', '#BM-011', 1),
  (25, 'Thương hiệu', 'Ewald Gelatine (Dòng Bronze, nhập khẩu Đức)', 2),
  (25, 'Hàm lượng & Đặc tính', '100% nguyên chất, độ bloom chuẩn dòng Bronze, không mùi không vị', 3),
  (25, 'Ứng dụng phù hợp', 'Làm bánh Mousse Chocolate, Panna Cotta, thạch trái cây và các món tráng miệng lạnh', 4),
  (25, 'Hướng dẫn sử dụng', 'Ngâm lá gelatine trong nước lạnh khoảng 5–7 phút cho mềm, vớt ra vắt nhẹ rồi hòa tan vào hỗn hợp ấm', 5),
  (25, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp và đậy kín sau khi sử dụng', 6),
  (26, 'Mã sản phẩm', '#BM-012', 1),
  (26, 'Thương hiệu', 'Arm & Hammer (Pure Baking Soda, nhập khẩu Mỹ)', 2),
  (26, 'Thành phần & Đặc tính', '100% Sodium Bicarbonate tinh khiết, chất tạo nở tự nhiên, an toàn thực phẩm', 3),
  (26, 'Ứng dụng phù hợp', 'Làm bánh Cookies bơ, bánh Chocolate Muffin, bánh quy gừng và các dòng bánh cần độ xốp giòn', 4),
  (26, 'Hướng dẫn sử dụng', 'Trộn đều bột baking soda với bột mì (khô) trước khi rây và trộn vào hỗn hợp lỏng để bánh nở đều', 5),
  (26, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát, đậy kín nắp hộp sau khi sử dụng để tránh bị hút ẩm', 6),
  (27, 'Mã sản phẩm', '#BM-013', 1),
  (27, 'Thương hiệu', 'Mauripan (Instant Dry Yeast, men chịu ngọt cao)', 2),
  (27, 'Thành phần & Đặc tính', 'Men tự nhiên Saccharomyces cerevisiae, độ nở mạnh, không cần kích hoạt trước', 3),
  (27, 'Ứng dụng phù hợp', 'Làm bánh mì hoa cúc, bánh mì ngọt, bánh bao, brioche và các loại bánh mì lên men', 4),
  (27, 'Hướng dẫn sử dụng', 'Trộn trực tiếp men khô vào bột mì (tránh để men tiếp xúc trực tiếp với muối hoặc đá lạnh trước khi trộn đều)', 5),
  (27, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát. Sau khi cắt gói nên dùng hết hoặc kẹp kín miệng, bảo quản ngăn mát tủ lạnh', 6),
  (28, 'Mã sản phẩm', '#BM-014', 1),
  (28, 'Thương hiệu', 'Philips (HR3705 Daily Collection)', 2),
  (28, 'Thông số kỹ thuật', 'Công suất 300W, 5 tốc độ + Chế độ Turbo tăng cường, chất liệu nhựa cao cấp và thép không gỉ', 3),
  (28, 'Ứng dụng phù hợp', 'Đánh bông Whipping cream, đánh trứng làm bánh bông lan, trộn bột làm bánh mì, cupcake, muffin', 4),
  (28, 'Hướng dẫn sử dụng', 'Lắp chặt que đánh/nhào trước khi cắm điện. Không hoạt động liên tục quá 5 phút mỗi lần để bảo vệ động cơ', 5),
  (28, 'Quy cách bảo quản', 'Vệ sinh que đánh bằng nước ấm và xà phòng sau khi dùng. Lau sạch thân máy bằng khăn mềm, cất nơi khô ráo', 6),
  (29, 'Mã sản phẩm', '#BM-015', 1),
  (29, 'Thương hiệu', 'Sanneng (Inox 304 thực phẩm cao cấp)', 2),
  (29, 'Chất liệu & Kích thước', 'Inox không gỉ dày dặn, có các size tùy chọn từ 18cm đến 26cm (hoặc mua trọn bộ 5 cái)', 3),
  (29, 'Ứng dụng phù hợp', 'Dùng để đánh trứng, trộn bột làm bánh bông lan, nhào bột bánh mì, đựng nguyên liệu làm bánh', 4),
  (29, 'Hướng dẫn sử dụng', 'Rửa sạch trước và sau khi sử dụng. Có thể dùng an toàn trong máy rửa bát', 5),
  (29, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát sau khi lau khô nước', 6),
  (30, 'Mã sản phẩm', '#BM-016', 1),
  (30, 'Thương hiệu', 'Sanneng (Inox 304 thực phẩm cao cấp)', 2),
  (30, 'Chất liệu & Kích thước', 'Inox không gỉ dày dặn, mắt lưới mịn đan khít, tay cầm dài kèm móc treo tiện dụng', 3),
  (30, 'Ứng dụng phù hợp', 'Rây bột mì, bột cacao, bột matcha trước khi trộn; lọc hỗn hợp trứng sữa làm bánh flan, mousse', 4),
  (30, 'Hướng dẫn sử dụng', 'Gác tai móc của rây lên thành tô trộn, đổ bột vào và gõ nhẹ vào thành rây để bột rơi đều', 5),
  (30, 'Quy cách bảo quản', 'Rửa sạch ngay sau khi dùng để tránh bột khô bám kẹt vào mắt lưới, lau khô trước khi cất', 6),
  (31, 'Mã sản phẩm', '#BM-017', 1),
  (31, 'Thương hiệu', 'Sanneng (Thép carbon phủ chống dính)', 2),
  (31, 'Chất liệu & Kích thước', 'Thép carbon dày dặn, dẫn nhiệt đều, khay gồm 6 lỗ tròn tiêu chuẩn nướng bánh cupcake/muffin', 3),
  (31, 'Ứng dụng phù hợp', 'Nướng bánh Cupcake Matcha, bánh Chocolate Muffin, bánh tart nhỏ và các loại bánh nướng khuôn nhỏ', 4),
  (31, 'Hướng dẫn sử dụng', 'Nên lót thêm giấy lót cup giấy vào khuôn trước khi đổ bột để bánh đẹp hơn và dễ lấy ra', 5),
  (31, 'Quy cách bảo quản', 'Rửa bằng mút mềm và nước ấm, không dùng búi sắt cọ rửa để bảo vệ lớp chống dính, lau khô trước khi cất', 6),
  (32, 'Mã sản phẩm', '#BM-018', 1),
  (32, 'Thương hiệu', 'Silikomart (Silicon thực phẩm nguyên sinh an toàn)', 2),
  (32, 'Chất liệu & Kích thước', 'Silicon dẻo cao cấp chịu nhiệt tốt từ -40°C đến 230°C, bề mặt chống dính tối ưu', 3),
  (32, 'Ứng dụng phù hợp', 'Làm kẹo dẻo, đổ khuôn socola nghệ thuật, thạch trái cây mini và các món tráng miệng', 4),
  (32, 'Hướng dẫn sử dụng', 'Đặt khuôn lên một khay phẳng trước khi đổ nguyên liệu để dễ di chuyển vào tủ lạnh hoặc lò nướng', 5),
  (32, 'Quy cách bảo quản', 'Rửa sạch bằng nước ấm, lau khô hoặc để ráo. Tránh tiếp xúc trực tiếp với ngọn lửa hoặc vật sắc nhọn', 6),
  (33, 'Mã sản phẩm', '#BM-019', 1),
  (33, 'Thương hiệu', 'Sanneng (Nhựa ABS nguyên sinh an toàn thực phẩm)', 2),
  (33, 'Chất liệu & Kích thước', 'Nhựa ABS cứng cáp, đường kính mặt bàn xoay 27.5cm (hoặc 35cm), chiều cao 6.5cm', 3),
  (33, 'Ứng dụng phù hợp', 'Dùng để chà láng cốt bánh gato, bóp kem trang trí bánh sinh nhật, bánh kem mousse và trưng bày bánh', 4),
  (33, 'Hướng dẫn sử dụng', 'Đặt cốt bánh lên tâm bàn xoay, kết hợp cùng dao chà láng để xoay mượt mà khi phủ kem', 5),
  (33, 'Quy cách bảo quản', 'Dùng khăn ẩm lau sạch hoặc rửa nhẹ nhàng sau khi dùng, tránh để nước ngâm trực tiếp vào ổ bi trục xoay', 6),
  (34, 'Mã sản phẩm', '#BM-020', 1),
  (34, 'Thương hiệu', 'Sanneng (Giấy Kraft/Ivory thực phẩm cao cấp)', 2),
  (34, 'Chất liệu & Kích thước', 'Giấy thực phẩm cứng cáp, thiết kế cửa sổ kính trong suốt, khay đựng cố định bánh', 3),
  (34, 'Ứng dụng phù hợp', 'Đóng gói và bảo quản bánh Cupcake, bánh Muffin, bánh tart để làm quà tặng hoặc bán hàng', 4),
  (34, 'Hướng dẫn sử dụng', 'Dựng khung hộp, lót khay định hình bên trong và đặt các viên bánh cupcake đã trang trí vào ngay ngắn', 5),
  (34, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát, tránh nơi ẩm ướt để giữ độ cứng cho hộp giấy', 6),
  (35, 'Mã sản phẩm', '#BM-021', 1),
  (35, 'Thương hiệu', 'Sanneng (Giấy Kraft nguyên sinh định lượng cao)', 2),
  (35, 'Chất liệu & Kích thước', 'Giấy kraft nâu dày dặn, đáy vuông chịu lực tốt, quai xách xoắn chắc chắn', 3),
  (35, 'Ứng dụng phù hợp', 'Đựng hộp bánh gato, hộp đựng cupcake, hộp bánh cookies làm quà tặng trong các dịp lễ, sinh nhật', 4),
  (35, 'Hướng dẫn sử dụng', 'Mở phẳng đáy túi, đặt hộp bánh ngay ngắn vào bên trong để giữ cố định form dáng', 5),
  (35, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát, tránh tiếp xúc trực tiếp với nước và độ ẩm cao', 6),
  (36, 'Mã sản phẩm', '#BM-022', 1),
  (36, 'Thương hiệu', 'Sanneng (Nhựa PE thực phẩm cao cấp trong suốt)', 2),
