  (36, 'Ứng dụng phù hợp', 'Đựng bánh cookies, bánh quy bơ, kẹo dẻo, các loại hạt dinh dưỡng và nguyên liệu làm bánh khô', 4),
  (36, 'Hướng dẫn sử dụng', 'Cho bánh đã nguội hẳn vào túi, miết chặt đường khóa zip từ đầu này sang đầu kia để đóng kín', 5),
  (36, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp và nhiệt độ cao', 6),
  (37, 'Mã sản phẩm', '#BM-023', 1),
  (37, 'Thương hiệu', 'Sanneng (Giấy bìa ép cứng cao cấp chống thấm)', 2),
  (37, 'Chất liệu & Kích thước', 'Bìa cứng ép nhiều lớp dày dặn, có hai phân loại dáng tròn và dáng vuông tiện dụng', 3),
  (37, 'Ứng dụng phù hợp', 'Dùng làm đế kê lót dưới cốt bánh kem, bánh gato, bánh sinh nhật để trang trí và vận chuyển', 4),
  (37, 'Hướng dẫn sử dụng', 'Đặt đế bánh lên bàn xoay trước khi chà láng cốt bánh để tiện lợi nhấc bánh ra sau khi hoàn thiện', 5),
  (37, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát, tránh tiếp xúc trực tiếp với nước hoặc môi trường ẩm ướt', 6),
  (38, 'Mã sản phẩm', '#BM-024', 1),
  (38, 'Thương hiệu', 'Sanneng (Giấy Kraft nguyên sinh & Nhựa PET nguyên sinh)', 2),
  (38, 'Chất liệu & Kích thước', 'Đế khay giấy kraft chống thấm dầu kèm nắp vòm trong suốt PET, có 3 size S, M, L đa dạng lựa chọn', 3),
  (38, 'Ứng dụng phù hợp', 'Đựng bánh Tiramisu, bánh cuộn Swiss Roll, bánh su kem, các loại bánh ngọt mang đi (takeaway)', 4),
  (38, 'Hướng dẫn sử dụng', 'Đặt bánh ngay ngắn vào khay giấy, đậy nắp nhựa PET khớp chặt các gờ để cố định chắc chắn', 5),
  (38, 'Quy cách bảo quản', 'Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp và nhiệt độ quá cao', 6),
  (39, 'Mã sản phẩm', '#BM-025', 1),
  (39, 'Thương hiệu', 'Sanneng (Hợp kim nhôm đúc thực phẩm cao cấp)', 2),
  (39, 'Chất liệu & Kích thước', 'Nhôm nguyên chất dày dặn, tản nhiệt đều, có 2 phân loại chính gồm dòng thành thấp và dòng thành cao', 3),
  (39, 'Ứng dụng phù hợp', 'Nướng bánh quy, bánh cuộn (thành thấp) hoặc nướng bánh bông lan Đài Loan, bánh gato, bánh mì (thành cao)', 4),
