  (39, 'Quy cách bảo quản', 'Rửa sạch bằng mút mềm sau khi dùng, lau khô hoàn toàn và cất ở nơi khô ráo', 6),
  (40, 'Mã sản phẩm', '#BM-026', 1),
  (40, 'Thương hiệu', 'Sanneng (Giấy bìa ép cứng phủ lớp chống thấm thực phẩm)', 2),
  (40, 'Chất liệu & Kích thước', 'Giấy ép cứng cáp, chống thấm nước và dầu tốt, gồm các phân loại tròn 5cm, tròn 8cm, vuông 10cm và bạc 12cm', 3),
  (40, 'Ứng dụng phù hợp', 'Dùng làm đế kê lót các loại bánh mousse, bánh flan gâteaux, bánh ngọt mini phục vụ tiệc hoặc bán take-away', 4),
