INSERT INTO recipes (id, slug, code, title, subtitle, category, tags_json, rating_avg, bake_minutes, time_label, difficulty, default_servings, servings_unit, yield_label, people_label, image_path, author, is_published) VALUES
  (1, 'recipe-bong-lan', 'RECIPE NO. 01', 'Bánh bông lan cơ bản', 'Cốt bánh mềm ẩm, bông xốp nhẹ tan nhờ bột mì số 8 và kỹ thuật ổn định lòng trắng.', 'Bánh ngọt', '[\"Bánh ngọt\",\"Bánh kem\"]', '4.90', 45, '60 phút', 'Trung bình', 1, 'Số ổ (20cm)', '1 ổ 20cm (4 người ăn)', '4 người', 'images/recipes/banh-bong-lan-co-ban.jpg', 'Minh Thư · BakeMate Studio', 1),
  (2, 'recipe-matcha-cupcake', 'RECIPE NO. 02', 'Bánh cupcake Matcha', 'Những chiếc cupcake mềm xốp, thơm nhẹ vị trà xanh Matcha, kết hợp cùng lớp kem Matcha béo mịn, tạo nên hương vị hài hòa và hấp dẫn.', 'Bánh ngọt', '[\"Bánh ngọt\",\"Bánh kem\"]', '4.80', 22, '50 phút', 'Dễ', 6, 'Số lượng (chiếc)', '6 chiếc (6 người ăn)', '6 người', 'images/recipes/banh-cupcake-matcha.jpg', 'Bảo Ngọc · BakeMate Kitchen', 1),
  (3, 'recipe-banh-quy-bo', 'RECIPE NO. 03', 'Cookies bơ', 'Hương bơ sữa Anchor 82.9% béo ngậy cùng từng đường vân hoa cúc giòn tan.', 'Bánh quy', '[\"Bánh quy\"]', '4.90', 18, '40 phút', 'Dễ', 1, 'Số mẻ (~30 chiếc/mẻ)', '~30 chiếc (6 người ăn)', '6 người', 'images/recipes/cookies-bo.jpg', 'Đen Ny · BakeMate Craft', 1),
  (4, 'recipe-hoa-cuc', 'RECIPE NO. 04', 'Bánh mì hoa cúc', 'Bánh mì hoa cúc có thớ bánh mềm dai, xốp nhẹ, thơm béo mùi bơ sữa và hương thơm đặc trưng. Bánh được tạo hình bện ba đẹp mắt.', 'Bánh mì', '[\"Bánh mì\"]', '4.80', 28, '120 phút', 'Khó', 2, 'Số ổ (450g)', '2 ổ 450g (4 người ăn)', '4 người', 'images/recipes/banh-mi-hoa-cuc.jpg', 'Gia Bảo · BakeMate Kitchen', 1),
  (5, 'recipe-muffin-socola', 'RECIPE NO. 05', 'Bánh Chocolate Muffin', 'Không cần máy đánh trứng — 45 phút có ngay khay muffin cacao Hershey\'s mềm ẩm đậm vị.', 'Bánh ngọt', '[\"Bánh ngọt\"]', '4.90', 25, '45 phút', 'Dễ', 6, 'Số lượng (chiếc)', '6 chiếc (6 người ăn)', '6 người', 'images/recipes/banh-chocolate-muffin.jpg', 'Bảo Ngọc · BakeMate Community', 1),
  (6, 'recipe-brownie', 'RECIPE NO. 06', 'Bánh Brownie', 'Lớp vỏ nứt bóng đẹp đặc trưng bọc lấy phần ruột ẩm dẻo đậm vị cacao nguyên chất.', 'Bánh ngọt', '[\"Bánh ngọt\"]', '4.90', 25, '50 phút', 'Dễ', 1, 'Số khuôn (20cm)', '1 khuôn 20cm (4 người ăn)', '4 người', 'images/recipes/banh-brownie.jpg', 'Nguyễn Thương · BakeMate Baker', 1),
  (7, 'recipe-mousse-socola', 'RECIPE NO. 07', 'Bánh Mousse Chocolate', 'Bánh Mousse Chocolate là món bánh lạnh có kết cấu mềm mịn, xốp nhẹ, mang hương vị chocolate cacao đậm đà tan nhẹ trong miệng.', 'Tráng miệng', '[\"Tráng miệng\",\"Bánh kem\",\"Bánh không cần lò nướng\"]', '4.80', 15, '75 phút', 'Trung bình', 1, 'Số ổ (20cm)', '1 ổ 20cm (4 người ăn)', '4 người', 'images/recipes/banh-mousse-chocolate.jpg', 'Minh Thư · BakeMate Studio', 1),
  (8, 'recipe-pancake', 'RECIPE NO. 08', 'Bánh Pancake mật ong', 'Những chiếc pancake vàng mềm, xốp nhẹ, thơm mùi bơ sữa, kết hợp cùng mật ong ngọt dịu, phù hợp cho bữa sáng hoặc bữa ăn nhẹ.', 'Bánh ngọt', '[\"Bánh ngọt\",\"Bánh không cần lò nướng\"]', '4.80', 10, '25 phút', 'Dễ', 8, 'Số lượng (chiếc)', '8 chiếc (4 người ăn)', '4 người', 'images/recipes/banh-pancake-mat-ong.jpg', 'Nguyễn Thương · BakeMate Baker', 1);
INSERT INTO recipe_steps (recipe_id, step_order, instruction) VALUES
  (1, 1, 'Tách riêng lòng đỏ và lòng trắng trứng gà ở nhiệt độ phòng; làm nóng trước lò nướng ở 165°C trong 15 phút.'),
  (1, 2, 'Khuấy đều lòng đỏ với Sữa tươi Vinamilk, dầu ăn và rây Bột mì số 8 vào trộn đến khi hỗn hợp mịn mượt.'),
  (1, 3, 'Đánh bông lòng trắng trứng với Bột làm bánh Tartar và Đường tinh luyện chia làm 3 lần đến khi đạt chóp mềm uốn cong.'),
  (1, 4, 'Chia hỗn hợp lòng trắng thành 3 phần, trộn nhẹ (fold) vào âu lòng đỏ rồi đổ vào khuôn 20cm nướng 40–45 phút.'),
  (2, 1, 'Chuẩn bị nguyên liệu: Cân đong các nguyên liệu làm cốt bánh và kem Matcha. Rây mịn bột mì và bột Matcha, chuẩn bị khuôn cupcake và giấy lót.'),
  (2, 2, 'Trộn hỗn hợp cốt bánh: Đánh bơ với đường đến khi hỗn hợp mềm mịn. Thêm trứng và sữa tươi không đường Vinamilk, sau đó kết hợp với hỗn hợp bột mì số 8 và Bột Matcha.'),
  (2, 3, 'Chia bột và nướng bánh: Chia đều hỗn hợp vào 6 khuôn cupcake đã lót giấy. Cho vào lò nướng ở 175°C khoảng 20–22 phút cho đến khi bánh chín vàng.'),
  (2, 4, 'Làm kem Matcha và trang trí: Đánh Whipping Cream với đường và Matcha đến khi đạt chóp mềm mịn. Cho kem vào túi bắt kem, trang trí lên cupcake sau khi bánh nguội hoàn toàn.'),
  (3, 1, 'Đánh bông Bơ lạt Anchor với đường tinh luyện đến khi bông mịn sáng màu, thêm trứng gà vào đánh quyện.'),
  (3, 2, 'Rây Bột mì Baker\'s Choice số 8 vào âu, dùng phới trộn đều thành khối bột mịn dẻo.'),
  (3, 3, 'Lắp đui sao lớn vào túi bắt kem, cho bột vào và bóp tạo hình bông hoa trên khay nhôm đã lót giấy nến.'),
  (3, 4, 'Nướng ở 170°C khoảng 15–18 phút đến khi viền bánh ngả vàng thơm giòn, đóng gói trong túi zip giữ độ giòn lâu.'),
  (4, 1, 'Chuẩn bị và trộn nguyên liệu: Cân đong Bột mì số 11, Men nở, đường, muối, trứng gà và Sữa tươi không đường Vinamilk; trộn đến khi hỗn hợp kết dính.'),
  (4, 2, 'Nhào bột và ủ lần một: Nhào bột đến khi khối bột mịn đàn hồi, thêm từng phần Bơ lạt Anchor mềm nhào tiếp đến khi kéo màng mỏng. Đậy kín ủ 50 phút cho nở gấp đôi.'),
  (4, 3, 'Tạo hình và ủ lần hai: Chia bột thành các phần bằng nhau, cán thành dải dài và bện ba tạo hình 2 ổ bánh mì hoa cúc 450g. Đặt lên khay và ủ lần hai 35 phút.'),
  (4, 4, 'Quét mặt và nướng bánh: Quét hỗn hợp trứng lên mặt bánh rồi nướng ở 175°C khoảng 25–28 phút đến khi chín vàng ruộm thơm nức.'),
  (5, 1, 'Làm nóng lò 180°C và xếp cup giấy nướng bánh vào Khuôn Nướng Cupcake & Muffin.'),
  (5, 2, 'Đun chảy Bơ lạt Anchor rồi khuấy tan Bột cacao Hershey\'s cùng đường tinh luyện.'),
  (5, 3, 'Đánh tan trứng với Sữa tươi Vinamilk, đổ vào âu bơ cacao rồi rây Bột mì đa dụng Meizan + Baking Soda vào khuấy vừa quyện.'),
  (5, 4, 'Chia đều bột đầy 2/3 cup giấy và nướng 22–25 phút ở 180°C.'),
  (6, 1, 'Đun cách thủy Bơ lạt Anchor và Bột cacao Hershey\'s ở 50–55°C cho quyện bóng mịn.'),
  (6, 2, 'Đánh trứng gà và đường tinh luyện đến khi hỗn hợp sáng màu, đường tan hoàn toàn rồi trộn vào bơ cacao.'),
  (6, 3, 'Rây nhẹ 85g Bột mì đa dụng Meizan vào hỗn hợp socola, trộn nhẹ vừa hết bột trắng.'),
  (6, 4, 'Đổ vào khuôn lót giấy nến chống dính và nướng ở 175°C trong 24–26 phút.'),
  (7, 1, 'Chuẩn bị nguyên liệu và khuôn bánh: Cân các nguyên liệu theo công thức, chuẩn bị khuôn tròn đế rời 20cm lót đế mousse; ngâm mềm Lá Gelatine Ewald trong nước lạnh.'),
  (7, 2, 'Xử lý hỗn hợp cacao & gelatine: Đun ấm Sữa tươi không đường Vinamilk, khuấy tan Bột cacao Hershey\'s và đường, vắt ráo Lá Gelatine hòa tan đều rồi để nguội về ~30°C.'),
  (7, 3, 'Đánh bông Whipping Cream & trộn mousse: Đánh bông lạnh Whipping Cream Anchor đến chóp mềm mịn, nhẹ nhàng fold cùng sốt cacao để giữ độ thoáng xốp.'),
  (7, 4, 'Làm lạnh và hoàn thiện: Đổ hỗn hợp mousse vào khuôn, dàn phẳng mặt và đặt ngăn mát tủ lạnh ít nhất 4 giờ. Tách khuôn nhẹ nhàng và rắc bột cacao trang trí.'),
  (8, 1, 'Chuẩn bị nguyên liệu: Cân đong Bột mì đa dụng Meizan, Baking Soda, trứng gà, Sữa tươi không đường Vinamilk, Bơ lạt Anchor và đường tinh luyện.'),
  (8, 2, 'Pha hỗn hợp pancake: Rây bột và Baking Soda vào tô, cho trứng gà, Sữa tươi Vinamilk và bơ đun chảy vào khuấy nhẹ vừa quyện mịn không vón cục.'),
  (8, 3, 'Chiên bánh pancake: Làm nóng chảo chống dính lửa nhỏ vừa, phết lớp bơ mỏng, dùng ca đong rót từng phần bột tròn đều; đợi mặt sủi bọt khí se viền rồi lật mặt.'),
  (8, 4, 'Hoàn thiện và thưởng thức: Chiên lần lượt đến khi đủ 8 chiếc pancake vàng đều hai mặt, xếp chồng ra đĩa rưới mật ong và thêm lát bơ.');
INSERT INTO recipe_tips (recipe_id, tip_order, tip_text) VALUES
  (1, 1, 'Dùng trứng gà ở nhiệt độ phòng giúp lòng trắng dễ đánh bông đạt chóp mềm và không bị tách nước.'),
  (1, 2, 'Luôn rây mịn bột mì số 8 trước khi trộn (fold) theo một chiều từ dưới đáy âu lên để giữ trọn bọt khí.'),
  (1, 3, 'Úp ngược khuôn ngay khi lấy ra khỏi lò để cốt bánh giữ độ cao phẳng mịn không bị xẹp mặt.'),
  (2, 1, 'Rây bột Matcha trước khi trộn để hạn chế tình trạng vón cục và giúp màu bánh phân bố đồng đều.'),
  (2, 2, 'Không trộn hỗn hợp bột quá lâu vì có thể khiến cốt cupcake bị chai và mất độ mềm xốp.'),
  (2, 3, 'Đảm bảo cupcake nguội hoàn toàn trước khi bắt kem để tránh lớp kem Matcha bị chảy.'),
  (2, 4, 'Khi đánh Whipping Cream, cần kiểm soát tốc độ và thời gian đánh để kem đạt độ bông phù hợp, không bị tách nước.'),
  (2, 5, 'Bảo quản cupcake đã trang trí kem trong ngăn mát tủ lạnh nếu chưa sử dụng ngay.'),
  (3, 1, 'Bơ lạt chỉ nên để mềm ấn nhẹ lún tay (khoảng 18–20°C), không đun chảy lỏng sẽ làm bánh bị chảy bè khi nướng.'),
  (3, 2, 'Làm lạnh khay bánh đã bắt hình 15 phút trong ngăn mát trước khi đưa vào lò để vân hoa giữ nguyên nét.'),
  (4, 1, 'Bơ lạt nên được bổ sung từ từ trong quá trình nhào để bột hấp thụ tốt, tránh cho toàn bộ bơ vào cùng lúc khiến hỗn hợp khó hòa quyện.'),
  (4, 2, 'Không sử dụng quá nhiều bột áo khi tạo hình vì có thể làm thay đổi tỷ lệ nguyên liệu và khiến bánh bị khô.'),
  (4, 3, 'Cần đảm bảo bột được nhào đủ độ đàn hồi trước khi ủ để bánh có thớ dai và mềm xốp.'),
  (4, 4, 'Không rút ngắn thời gian ủ bột tùy tiện vì bánh có thể không nở đủ.'),
  (4, 5, 'Để bánh nguội hoàn toàn trước khi cho vào túi hoặc hộp kín nhằm hạn chế hơi nước làm bánh bị ẩm.'),
  (5, 1, 'Hòa tan cacao vào bơ ấm giúp khơi dậy hương thơm chocolate sâu hơn hẳn khi trộn khô.'),
  (5, 2, 'Không khuấy quá lâu sau khi rây bột mì đa dụng Meizan để bánh giữ độ tơi xốp đặc trưng.'),
  (6, 1, 'Giữ hỗn hợp bơ + cacao đun cách thủy quanh 50–55°C và đánh tan hoàn toàn đường với trứng để mặt bánh bóng vỡ.'),
  (6, 2, 'Lót dư hai mép giấy nến để dễ dàng nhấc nguyên khối Brownie ra khỏi khay cắt vuông vức.'),
  (7, 1, 'Đảm bảo hỗn hợp cacao đã nguội bớt trước khi trộn với Whipping Cream để tránh làm kem bị tan.'),
  (7, 2, 'Không đánh Whipping Cream quá cứng vì có thể khiến mousse khó hòa quyện và kém mịn.'),
  (7, 3, 'Khi kết hợp các hỗn hợp, nên dùng thao tác fold nhẹ nhàng từ dưới đáy âu lên để giữ độ xốp.'),
  (7, 4, 'Làm lạnh đủ thời gian ít nhất 4 giờ trước khi tháo khuôn để bánh giữ được hình dáng sắc nét.'),
  (8, 1, 'Không khuấy hỗn hợp bột quá lâu vì có thể khiến pancake bị dai và mất độ mềm xốp.'),
  (8, 2, 'Nên để hỗn hợp bột nghỉ khoảng 5–10 phút trước khi chiên giúp bột mịn đều.'),
  (8, 3, 'Sử dụng lửa nhỏ đến vừa để bánh chín đều từ trong ra ngoài không bị cháy mặt.'),
  (8, 4, 'Chỉ lật bánh khi mặt trên xuất hiện các bọt khí nhỏ đều và phần viền bắt đầu se lại.'),
  (8, 5, 'Phết một lớp bơ mỏng lên chảo để tạo mùi thơm, tránh dùng quá nhiều gây ngấy.');
